draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw worker
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw product
  ctx.beginPath();
  ctx.rect(W/2 + 100, H/2, 50, 50);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // disconnection
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 70);
  ctx.lineTo(W/2 + 100, H/2);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.setLineDash([10, 10]);
  ctx.stroke();
  ctx.setLineDash([]);

  // alienation effect
  ctx.fillStyle = 'black';
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.globalAlpha = 1;

  ctx.restore();
}
